import React, {useRef} from 'react';
import {MenuStopRefresh} from '../utils/MenuStopRefresh';
import {View, StyleSheet} from 'react-native';
import {createNavigatorFactory, useNavigationBuilder, TabRouter, NavigationHelpersContext} from '@react-navigation/native';
import {FloatingDock} from '../components/FloatingDock/FloatingDock';
import {FooterClearanceProvider} from '../components/FloatingDock/FooterClearance';

// Только маршрутизация: BottomTabBar и его измерения здесь не используются.
function FloatingNavigator({children, initialRouteName = 'Catalog', screenOptions}) {
    const {state, navigation, descriptors, NavigationContent} = useNavigationBuilder(TabRouter, {
        children, initialRouteName, screenOptions, backBehavior: 'history'
    });
    const visited = useRef(new Set());
    visited.current.add(state.routes[state.index].key);
    // В старых версиях navigation нет NavigationContent.
    const Content = NavigationContent || NavigationHelpersContext.Provider;
    return <Content value={navigation}>
        <FooterClearanceProvider><View style={styles.root}>
            <MenuStopRefresh/>
            <View style={styles.content}>
                {state.routes.map((route, index) => visited.current.has(route.key) ?
                    <View key={route.key} accessibilityElementsHidden={index !== state.index}
                        importantForAccessibility={index === state.index ? 'auto' : 'no-hide-descendants'}
                        pointerEvents={index === state.index ? 'auto' : 'none'}
                        style={[StyleSheet.absoluteFill, {display: index === state.index ? 'flex' : 'none'}]}>
                        {descriptors[route.key].render()}
                    </View> : null)}
            </View>
            <FloatingDock state={state} navigation={navigation}/>
        </View></FooterClearanceProvider>
    </Content>;
}
const styles = StyleSheet.create({
    root: {flex:1, minHeight:0, position:'relative'},
    content: {flex:1, minHeight:0, position:'relative', zIndex:0}
});
export const createFloatingNavigator = createNavigatorFactory(FloatingNavigator);
