import bridge from '@vkontakte/vk-bridge';

let initRequest = null;

// VK должен показать iframe ещё до выбора города и городозависимых запросов.
// Корень приложения и каталог используют один результат инициализации.
export function ensureVkInitialized() {
    if (!initRequest) {
        initRequest = Promise.resolve().then(() => bridge.send('VKWebAppInit')).catch(error => {
            initRequest = null;
            throw error;
        });
    }
    return initRequest;
}
