import React from 'react';
import {Image, View, Text, Pressable} from 'react-native';
import {useDispatch, useSelector} from 'react-redux';
import {URL_SITE} from '../../store/types';
import {THEME} from '../../theme';
import {updateActiveGifts} from '../../store/actions/post';
import {money} from './model';

// Выбор использует тот же объект подарка и action, что существующая корзина.
export function GiftContents({gifts, sum, blocked}) {
    const dispatch = useDispatch();
    const active = useSelector(s => s.post.activeGift);
    const items = Object.values(gifts?.OneGift || {}).flatMap(group => Object.values(group || {}))
        .filter(item => item && Number.isFinite(Number(item.min_sum)))
        .sort((a,b) => Number(a.min_sum)-Number(b.min_sum));
    if (!items.length) return <Text>Сейчас подарки недоступны.</Text>;
    return <View>
        {blocked ? <Text style={{fontSize:13,color:'#777',marginBottom:12}}>Промокоды и подарки не суммируются.</Text> : null}
        {items.map((item,index) => {
            const remaining = Math.max(0, Number(item.min_sum)-sum);
            const selected = active && String(active.id_tovar) === String(item.id_tovar)
                && String(active.type_product) === String(item.type_product);
            const available = remaining === 0 && !blocked;
            return <View key={String(item.id_tovar)+'-'+index}
                style={{flexDirection:'row',alignItems:'center',paddingVertical:12,borderBottomWidth:1,borderBottomColor:'#eee'}}>
                {item.img ? <Image source={{uri:URL_SITE+'/images/tovars/'+item.img}}
                    style={{width:56,height:56,marginRight:12,borderRadius:8}}/> : null}
                <View style={{flex:1,minWidth:0}}>
                    <Text style={{fontSize:14,fontWeight:'600',color:'#252527'}}>{String(item.title || '').trim()}</Text>
                    <Text style={{fontSize:12,color:'#777',marginTop:3}}>{item.count_product || 1} шт. · {item.type_product_text || ''}</Text>
                    <Text style={{fontSize:12,color:'#777',marginTop:3}}>{remaining > 0 ? 'Добавьте ещё на '+money(remaining) : 'Доступен к заказу'}</Text>
                </View>
                <Pressable accessibilityRole="button" disabled={!available && !selected}
                    accessibilityLabel={(selected ? 'Убрать подарок ' : 'Выбрать подарок ')+item.title}
                    onPress={() => {if(selected) dispatch(updateActiveGifts(false)); else if(available) dispatch(updateActiveGifts(item));}}
                    style={{paddingVertical:12,paddingLeft:10}}>
                    <Text style={{fontSize:13,fontWeight:'600',color:available || selected ? THEME.MAIN_COLOR : '#999'}}>
                        {selected ? 'Убрать' : available ? 'Выбрать' : 'От '+money(item.min_sum)}
                    </Text>
                </Pressable>
            </View>;
        })}
    </View>;
}
