export const money = value => Math.round(Math.max(0, Number(value) || 0)).toLocaleString('ru-RU') + ' ₽';

export function countBasket(basket, toppings) {
    return (Array.isArray(basket) ? basket : []).reduce((sum, item) =>
        sum + (Array.isArray(item.type) ? item.type : []).reduce((n, type) => n + Math.max(0, Number(type.count) || 0), 0), 0)
        + (Array.isArray(toppings) ? toppings : []).reduce((sum, item) => sum + Math.max(0, Number(item.count) || 0), 0);
}

export function giftProgress(gifts, sum) {
    const steps = Object.values(gifts?.ListGift || {}).map(item => Number(item?.min_price))
        .filter(value => Number.isFinite(value) && value >= 0).sort((a,b) => a-b);
    if (!gifts?.ready || !steps.length) return null;
    const next = steps.find(value => value > sum);
    return {ready: sum >= steps[0], remaining: Math.max(0, (next ?? steps[steps.length-1]) - sum),
        progress: Math.min(1, Math.max(0, sum / Math.max(1, Number(gifts?.settingsScale?.max_summa) || steps[steps.length-1])))};
}

export function ringSegments(calculation) {
    const ranges = calculation?.ranges || [];
    if (!ranges.length) return [];
    const length = 2 * Math.PI * 25, slot = length / ranges.length;
    const segment = Math.max(0, slot - Math.min(5, slot * .18));
    return ranges.map((range, index) => {
        const progress = index < calculation.currentIndex ? 1 : index > calculation.currentIndex ? 0 :
            range.to === null ? 1 : Math.max(.08, Math.min(1,
                (calculation.calculationSum - range.from + 1) / Math.max(1, range.to - range.from + 1)));
        return {length, slot, segment, progress, index};
    });
}
