import axios from 'axios';

const failures = new Map();
const listeners = new Set();
let offline = typeof navigator !== 'undefined' && navigator.onLine === false;
export const getConnectionStatus = () => offline || failures.size > 0;
const notify = () => listeners.forEach(fn => fn(getConnectionStatus()));
export const subscribeConnectionStatus = fn => { listeners.add(fn); return () => listeners.delete(fn); };
const key = config => {
    const url = String(config?.url || '');
    return url.includes('/api/') ? url.split('&')[0].split('?')[0] : null;
};
axios.interceptors.request.use(config => {
    const endpoint = key(config);
    if (endpoint) {
        config.connectionStartedAt = Date.now();
        config.connectionTimer = setTimeout(() => {
            failures.set(endpoint, config.connectionStartedAt); notify();
        }, 8000);
    }
    return config;
});
axios.interceptors.response.use(response => {
    clearTimeout(response.config?.connectionTimer);
    const endpoint = key(response.config);
    if (endpoint && (failures.get(endpoint) || 0) <= response.config.connectionStartedAt) {
        failures.delete(endpoint); notify();
    }
    return response;
}, error => {
    clearTimeout(error.config?.connectionTimer);
    const endpoint = key(error.config);
    if (endpoint && !axios.isCancel(error) &&
        (['ECONNABORTED','ETIMEDOUT','ERR_NETWORK'].includes(error.code) ||
         (!error.response && error.request) || [502,503,504].includes(error.response?.status))) {
        failures.set(endpoint, error.config.connectionStartedAt || Date.now()); notify();
    } else if (endpoint && (failures.get(endpoint) || 0) <= error.config.connectionStartedAt) {
        failures.delete(endpoint); notify();
    }
    return Promise.reject(error);
});
if (typeof window !== 'undefined') {
    window.addEventListener('offline', () => { offline = true; notify(); });
    // Наличие сети ещё не означает доступность API; его ошибки снимет успешный запрос.
    window.addEventListener('online', () => { offline = false; notify(); });
}
