export function normalizePromocodeLanguage(mode) {
    return [0, 1, 2, '0', '1', '2'].includes(mode) ? Number(mode) : 1;
}

export function filterPromocode(value, mode) {
    const text = String(value || '');
    switch (normalizePromocodeLanguage(mode)) {
        case 0: return text.replace(/[^0-9A-Za-zА-Яа-яЁё]/g, '');
        case 2: return text.replace(/[^0-9А-Яа-яЁё]/g, '');
        default: return text.replace(/[^0-9A-Za-z]/g, '');
    }
}

export function promocodeLanguageHint(mode) {
    switch (normalizePromocodeLanguage(mode)) {
        case 0: return 'Цифры, латинские и русские буквы';
        case 2: return 'Цифры и русские буквы';
        default: return 'Цифры и латинские буквы';
    }
}
